\set ECHO none

-- Vulnerability 1: NULL UpsertClause with an old backend version.
\! port="25432"; out="/tmp/dolphin_security_upsert_clause_$$.out"; timeout 30s gsql "dbname=contrib_regression port=$port backend_version=92072" -c "INSERT INTO t_rep_tmp_1 VALUES(1, 1, 'C3', '{1,2,3}', '{10,20,30,40,50}', ROW(10,20), ROW(100, ROW(10,20), '{100,200}')), (1, 2, 'C3', '{1,2,3}', '{10,20,30,40,50}', ROW(10,20), ROW(100, ROW(10,20), '{100,200}')) ON DUPLICATE KEY UPDATE NOTHING;" > "$out" 2>&1; rc=$?; if [ "$rc" -eq 124 ] || ! grep -q "ERROR:" "$out"; then cat "$out"; rm -f "$out"; exit 1; fi; echo "security_upsert_clause: completed without backend crash"; rm -f "$out"

-- Vulnerabilities 2 and 3 use isolated SQL_ASCII databases and raw-byte SQL.
\c "dbname=contrib_regression"
\! port="25432"; db="dolphin_security_schema_ascii"; sql="/tmp/${db}_$$.sql"; out="/tmp/${db}_$$.out"; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; gsql -d postgres -p "$port" -c "CREATE DATABASE $db dbcompatibility 'B' ENCODING 'SQL_ASCII' TEMPLATE template0 LC_COLLATE 'C' LC_CTYPE 'C';" >/dev/null 2>&1 || exit 1; gsql -d "$db" -p "$port" -c "CREATE EXTENSION IF NOT EXISTS dolphin;" >/dev/null 2>&1 || exit 1; python3 -c 'import sys; sys.stdout.buffer.write(bytes.fromhex("53454c45435420615b315d2c20625b315d5b315d5b315d2c20635b315d2c20645b315d5b315d2820655b305d204652cececececececececececece"))' > "$sql"; PGCLIENTENCODING=SQL_ASCII timeout 30s gsql -d "$db" -p "$port" -f "$sql" > "$out" 2>&1; rc=$?; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; if [ "$rc" -eq 124 ] || ! grep -q "ERROR:" "$out"; then cat "$out"; rm -f "$sql" "$out"; exit 1; fi; echo "security_schema_null: completed without backend crash"; rm -f "$sql" "$out"

\! port="25432"; db="dolphin_security_truncate_ascii_b"; sql="/tmp/${db}_$$.sql"; out="/tmp/${db}_$$.out"; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; gsql -d postgres -p "$port" -c "CREATE DATABASE $db dbcompatibility 'B' ENCODING 'SQL_ASCII' TEMPLATE template0 LC_COLLATE 'C' LC_CTYPE 'C';" >/dev/null 2>&1 || exit 1; gsql -d "$db" -p "$port" -c "CREATE EXTENSION IF NOT EXISTS dolphin;" >/dev/null 2>&1 || exit 1; python3 -c 'import sys; sys.stdout.buffer.write(bytes.fromhex(""))' > "$sql"; PGCLIENTENCODING=SQL_ASCII timeout 30s gsql -d "$db" -p "$port" -f "$sql" > "$out" 2>&1; rc=$?; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; if [ "$rc" -eq 124 ] || ! grep -q "ERROR:" "$out"; then cat "$out"; rm -f "$sql" "$out"; exit 1; fi; echo "security_truncate_identifier_b: completed without backend crash"; rm -f "$sql" "$out"

\! port="25432"; db="dolphin_security_truncate_ascii_a"; sql="/tmp/${db}_$$.sql"; out="/tmp/${db}_$$.out"; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; gsql -d postgres -p "$port" -c "CREATE DATABASE $db dbcompatibility 'A' ENCODING 'SQL_ASCII' TEMPLATE template0 LC_COLLATE 'C' LC_CTYPE 'C';" >/dev/null 2>&1 || exit 1; python3 -c 'import sys; sys.stdout.buffer.write(bytes.fromhex(""))' > "$sql"; PGCLIENTENCODING=SQL_ASCII timeout 30s gsql -d "$db" -p "$port" -f "$sql" > "$out" 2>&1; rc=$?; gsql -d postgres -p "$port" -c "DROP DATABASE IF EXISTS $db;" >/dev/null 2>&1 || true; if [ "$rc" -eq 124 ] || ! grep -q "ERROR:" "$out"; then cat "$out"; rm -f "$sql" "$out"; exit 1; fi; echo "security_truncate_identifier_a: completed without backend crash"; rm -f "$sql" "$out"
